import{z as s,x as i,o as e,c as o,q as B,j as r,D as a,d as t,s as l,S as n}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"评测报告规范","description":"","frontmatter":{"title":"评测报告规范","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aeval-reporting-standard.md","filePath":"llm/aeval-reporting-standard.md","lastUpdated":1791063341000}'),d={name:"llm/aeval-reporting-standard.md"};function p(h,E,m,C,_,D){const A=i("Mermaid");return e(),o("div",null,[E[2]||(E[2]=B('<h1 id="评测报告规范" tabindex="-1">评测报告规范 <a class="header-anchor" href="#评测报告规范" aria-label="Permalink to &quot;评测报告规范&quot;">​</a></h1><div class="epigraph"><p>一个不能被第三方复现的分数不是证据，是广告；报告的任务是把广告变成证据，同时不把它变成攻击手册。</p><footer>—— 据公开模型卡与安全套件（HarmBench、JailbreakBench）文档的披露口径整理</footer></div><p><a href="/llm/aeval-adversarial-robustness">上一课</a>把鲁棒评测收成攻击族矩阵与最坏值门禁。数字跑齐了，最后一公里是报告：让分数可审计、可复现、可比较，又不外泄配方。本课程前九课产出的每一类数字，都要能落进这一课的字段标准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有规范的报告怎么失效，每条都有真实形态。「我们的模型 ASR 降低六成」——相对什么基准、什么裁判、哪版政策、什么解码，全部缺失；下一任拿到的是一句无法质疑也无法复现的话。裁判升级后，新旧数字混排成一条假时间序列，模型没动，尺子动了。安全数字单边披露（只报 ASR 不报过拒绝），优化沿着披露的那一侧滑向极端工作点——第一课封顶的作弊策略，被不完整的报告重新放行。最后，负结果不上墙：只有成功案例可见，防御的「复测失败」这类最有价值的知识沉底。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="五件套与结果规范" tabindex="-1">五件套与结果规范 <a class="header-anchor" href="#五件套与结果规范" aria-label="Permalink to &quot;五件套与结果规范&quot;">​</a></h3><p>每个数字绑五件套：<strong>检查点哈希、政策版本、套件版本、裁判版本与提示哈希、解码与 harness 配置</strong>。<span class="marginnote">「五件套」翻译成大白话：它是给每个分数配的出生证明——模型是哪一版（检查点哈希）、按哪套规矩测（政策版本）、用哪套题（套件版本）、谁当裁判（裁判版本与提示哈希）、答案怎么生成（解码与 harness 配置）。少了任何一项，别人拿到的就只是一个孤零零的数，而不是一个能重新测出来的数。</span><a href="/llm/model-cards">模型卡</a>是公开载体，内部报告是全量源。结果规范四条：区间不报点；成对指标同表（ASR 与过拒绝、准确与弃权、附和与纠正，沿本课程三根轴）；分域剖面不报单一总分；门禁定义写明——回归阈值、最坏值口径、判分一致率下限。披露分级：内部报告全量并索引私有回归集；对外披露聚合指标与套件名，不含未公开失败题面全文与攻击配方。时效声明：每个数字带日期与依赖版本，过期即声明失效。</p>',8)),(e(),r(n,null,{default:a(()=>[l(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20META%5B%22%E8%BF%90%E8%A1%8C%E5%85%83%E6%95%B0%E6%8D%AE%EF%BC%9A%E4%BA%94%E4%BB%B6%E5%A5%97%22%5D%20--%3E%20RES%5B%22%E7%BB%93%E6%9E%9C%E8%A1%A8%EF%BC%9A%E5%8C%BA%E9%97%B4%20%2B%20%E6%88%90%E5%AF%B9%E6%8C%87%E6%A0%87%22%5D%0A%20%20RES%20--%3E%20PROF%5B%22%E5%88%86%E5%9F%9F%E5%89%96%E9%9D%A2%E4%B8%8E%E9%97%A8%E7%A6%81%E5%AE%9A%E4%B9%89%22%5D%0A%20%20PROF%20--%3E%20INT%5B%22%E5%86%85%E9%83%A8%E6%8A%A5%E5%91%8A%EF%BC%9A%E5%85%A8%E9%87%8F%20%2B%20%E5%9B%9E%E5%BD%92%E9%9B%86%E7%B4%A2%E5%BC%95%22%5D%0A%20%20INT%20--%3E%20EXT%5B%22%E5%AF%B9%E5%A4%96%E6%8A%AB%E9%9C%B2%EF%BC%9A%E8%81%9A%E5%90%88%20%2B%20%E8%84%B1%E6%95%8F%22%5D%0A%20%20INT%20--%3E%20EXP%5B%22%E6%97%B6%E6%95%88%E4%B8%8E%E8%BF%87%E6%9C%9F%E5%A3%B0%E6%98%8E%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>版本绑定为什么等于可复现性：分数是三元组 \\(S(\\theta,P,J)\\)，报告本质上是把三元组连同采样过程一起钉下来；上一课的「尺子换了」事故，在字段层就是裁判版本缺失。<span class="marginnote">\\(S(\\theta,P,J)\\) 读作「分数由三根轴决定」：\\(\\theta\\) 是模型权重（哪一版检查点），\\(P\\) 是政策（提示词与安全规则），\\(J\\) 是裁判（给答案打分的模型或规则）。把分数想象成一台三旋钮机器的读数：任何一根旋钮被拧动，读数就不再是原来那个数——这就是报告必须连旋钮位置一起记录的原因。</span>成对同表为什么防博弈：任何单边指标的最优点都在极端工作点上（全拒、全弃权、全附和），同表让每个极端都顶着它的镜像数字，读者与门禁都看得见滑动。<span class="marginnote">初学者容易以为「指标越好模型越安全」，实际上只看单一指标反而会奖励作弊：模型只要学会「来者一律拒绝」，攻击成功率自然趋近零，但正常用户也被全挡在门外。成对同表相当于给每个优点配一个体温计——ASR 降了多少，过拒绝就升多少，两格并排看才看得出是真变好还是只是变保守。</span>负结果归档为什么是知识而不是丑闻：红队复测失败、消融不显著、探针失效，这些记录直接决定下一轮劳动花在哪——只在墙上放成功，等于给幸存者偏差发工资。<span class="marginnote">只看成功案例，就像只采访彩票中奖者：你会误以为买彩票是稳妥的理财方式。把「防御复测失败」「消融不显著」也贴上墙，团队才知道哪条路已经堵死、下一轮力气该花在哪——负结果是替团队省下真金白银的路标，不是谁的黑历史。</span></p>',2)),(e(),r(n,null,{default:a(()=>[l(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%8F%AA%E6%8A%AB%E9%9C%B2%E5%8D%95%E4%B8%80%E6%8C%87%E6%A0%87%EF%BC%9AASR%22%5D%20--%3E%20B%5B%22%E4%BC%98%E5%8C%96%E6%B2%BF%E6%8A%AB%E9%9C%B2%E4%BE%A7%E6%89%BE%E6%9C%80%E4%BD%8E%E5%88%86%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%BB%91%E5%90%91%E6%9E%81%E7%AB%AF%E5%B7%A5%E4%BD%9C%E7%82%B9%EF%BC%9A%E6%9D%A5%E8%80%85%E4%B8%80%E5%BE%8B%E6%8B%92%E7%BB%9D%22%5D%0A%20%20C%20--%3E%20D%5B%22ASR%20%E8%B6%8B%E8%BF%91%200%EF%BC%8C%E8%BF%87%E6%8B%92%E7%BB%9D%E9%A3%99%E5%8D%87%22%5D%0A%20%20D%20--%3E%20E%5B%22%E9%95%9C%E5%83%8F%E6%95%B0%E5%AD%97%E7%BC%BA%E5%A4%B1%EF%BC%8C%E6%97%A0%E4%BA%BA%E5%AF%9F%E8%A7%89%22%5D%0A%20%20F%5B%22%E6%88%90%E5%AF%B9%E5%90%8C%E8%A1%A8%EF%BC%9AASR%20%E4%B8%8E%E8%BF%87%E6%8B%92%E7%BB%9D%E5%B9%B6%E6%8E%92%22%5D%20--%3E%20G%5B%22%E6%AF%8F%E4%B8%AA%E6%9E%81%E7%AB%AF%E9%A1%B6%E7%9D%80%E9%95%9C%E5%83%8F%E6%95%B0%E5%AD%97%22%5D%0A%20%20G%20--%3E%20H%5B%22%E6%BB%91%E5%8A%A8%E5%9C%A8%E6%8A%A5%E5%91%8A%E4%B8%8A%E7%9B%B4%E6%8E%A5%E5%8F%AF%E8%A7%81%22%5D%0A%20%20H%20--%3E%20I%5B%22%E9%97%A8%E7%A6%81%E6%8C%89%E5%B7%A5%E4%BD%9C%E7%82%B9%E6%8B%A6%E6%88%AA%E6%9E%81%E7%AB%AF%E8%A7%A3%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">一行自检：任何安全数字，若拿掉五件套中任何一项就不能解释，它还没到能写进报告的程度。反过来，能从内部报告逐字段导出对外版本，两套事实才不会分叉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>报告不是监控：写报告时模型在变、用户在变、攻击在变，线上漂移归<a href="/llm/deployment-monitoring">部署监控</a>，报告绑定的是当时的静态证据。透明与滥用的权衡没有完美解，分级披露是折中而非原则问题：对外少披露不是隐瞒，是把配方留在私有回归集里。内外两版必须同源——对外数字若不能从内部报告导出，审计时两套事实会当场打架。最后，报告里给结论留位置时克制一点：本课程交付的口径是「在声明的工作点上，失败率的区间与最坏值」，超过这句的「安全」承诺都超出了测量的边界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五件套随每个数字发布：检查点、政策、套件、裁判、解码；缺一即不可复现。</li><li>结果规范四条：区间、成对同表、分域剖面、门禁定义。</li><li>披露分级且同源：对外可从内部逐字段导出，配方留在私有回归集。</li><li>负结果归档：复测失败与探针失效是下一轮劳动的路标。</li><li>每个数字带日期与版本，过期声明失效；报告是静态证据，不是线上监控。</li><li>出处：公开模型卡与 HarmBench、JailbreakBench 文档口径；Bai et al., 2022 的工作点报告方式。</li></ul>',5))])}const u=s(d,[["render",p]]);export{c as __pageData,u as default};
